# -*- coding: utf-8 -*-
S = "полный обзор задач 10–11 классов (очередь G9–G11) и скан искажённых дробей $\\left(\\frac{a}{b}\\right)^2$ вместо $\\frac{a}{b^2}$, проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
G = "в ключе вместо $-\\frac{a}{b^{2}}$ было записано $\\left(\\frac{-a}{b}\\right)^{2}$ (это $+\\frac{a^{2}}{b^{2}}$)"
E("G10_TB_§35_35_10_1", G + "; $\\left(\\frac3x\\right)'=-\\frac{3}{x^{2}}$", k=r"$-\dfrac{3}{x^{2}}$")
E("G11_TB_§4_4_33_а", G + "; $\\left(\\frac1x\\right)'=-\\frac{1}{x^{2}}$", k=r"$-\dfrac{1}{x^{2}}$")
E("G10_TB_§36_1", G + "; $y'=-\\frac{1}{x^{2}}-\\cos x+8x$", k=r"$-\dfrac{1}{x^{2}} - \cos x + 8x$")
E("G10_TB_§36_36_12_9", G + "; $y'=-\\frac{4}{(4x+5)^{2}}$", k=r"$-\dfrac{4}{(4x + 5)^{2}}$")
E("G11_TB_§4_4_33_б", "$y=\\left(\\frac1x\\right)^{2}=x^{-2}$, $y'=-2x^{-3}=-\\frac{2}{x^{3}}$; ключ был искажён до $\\left(\\frac{-2}{x}\\right)^{3}$", k=r"$-\dfrac{2}{x^{3}}$")
E("G11_TB_4_5_4_33_е", "$y=\\frac{4-x^{2}}{x}=\\frac4x-x$, $y'=-\\frac{4}{x^{2}}-1$; ключ был искажён до $-1-\\left(\\frac{4}{x}\\right)^{2}$ ($=-1-\\frac{16}{x^{2}}$)", k=r"$-1 - \dfrac{4}{x^{2}}$")
E("G10_TB_§36_36_9_4", "$g(f(x))=2\\cdot\\frac{1}{x^{2}}-\\frac{3}{x}+1$; в ключе было $\\left(\\frac2x\\right)^{2}=\\frac{4}{x^{2}}$",
  k=r"$y = \dfrac{1}{2x^{2} - 3x + 1}$; $y = \dfrac{2}{x^{2}} - \dfrac{3}{x} + 1$")
E("G10_TB_§35_35_11_1", "в условии и в ключе формулы $-\\frac{1}{x^{2}}$ и $\\frac{2}{x^{3}}$ были искажены записью $\\left(\\frac{-1}{x}\\right)^{2}$ и $\\left(\\frac2x\\right)^{3}$ (пояснения к вариантам исходят из $f=-x^{-2}$)",
  q=r"Пользуясь определением производной, найдите $f'(x)$, если: $f(x) = -\dfrac{1}{x^{2}}$", k=r"$\dfrac{2}{x^{3}}$")
E("G10_TB_§31_31_8_6", "$\\cos(\\frac{3\\pi}{2}+2x)=\\sin2x$: $\\sin6x=2\\sin2x\\iff\\sin2x(1-4\\sin^22x)=0$, откуда $x=\\frac{\\pi n}{2}$ и $x=\\pm\\frac{\\pi}{12}+\\frac{\\pi k}{2}$; прежний ключ не удовлетворял уравнению (например, $x=\\frac{\\pi}{4}$)",
  k=r"$x = \dfrac{\pi n}{2}$; $x = \pm\dfrac{\pi}{12} + \dfrac{\pi k}{2}$",
  dnew={0: (r"$x = \dfrac{\pi n}{2}$", "Ученик потерял серию решений уравнений $\\sin2x=\\pm\\frac12$."),
        1: (r"$x = \dfrac{\pi n}{2}$; $x = \pm\dfrac{\pi}{6} + \dfrac{\pi k}{2}$", "Ученик из $\\sin2x=\\frac12$ получил $2x=\\frac{\\pi}{6}$ и забыл поделить на $2$ ($x=\\frac{\\pi}{6}$ вместо $\\frac{\\pi}{12}$)."),
        2: (r"$x = \dfrac{\pi n}{2}$; $x = \pm\dfrac{\pi}{12} + \pi k$", "Ученик взял период $\\pi$ вместо $\\frac{\\pi}{2}$ для серии $\\pm\\frac{\\pi}{12}$ и потерял корни $\\frac{5\\pi}{12}$, $\\frac{7\\pi}{12}$.")})
